INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(37511, 'Numbers 34:8', 'Numbers', 34, 8, 'له هغې وروسته به هغه د حمات د غاښي په لاره صدد ته ورسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers34_verse_8.mp3', '', 1761754199, 1761754199),
(37512, 'Numbers 34:9', 'Numbers', 34, 9, 'د صدد څخه به سرحد په ختیځ کې زفرون ته ورسیږي او په حصرعینان کې به پای ته ورسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers34_verse_9.mp3', '', 1761754199, 1761754199),
(37513, 'Numbers 34:10', 'Numbers', 34, 10, 'ختیځ سرحد به په شمال کې په حصرعینان کې پیل شي، بیا به جنوب خواته شفام', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers34_verse_10.mp3', '', 1761754199, 1761754199),
(37514, 'Numbers 34:11', 'Numbers', 34, 11, 'او ربله ته ورسیږي چې د عین په ختیځې خوا کې دی. د هغه ځای څخه به هغه د جنوب په لور د جلیل د بحیرې ختیځو غونډیو ته ورسیږي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers34_verse_11.mp3', '', 1761754199, 1761754199),
(37515, 'Numbers 34:12', 'Numbers', 34, 12, 'بیا به د اردن د سیند په لاره د مړې بحیرې د شمالي برخې اخرني سرته ورسیږي. کومه ځمکه چې د هغو څلورو سرحدونو په منځ کې وي، هغه به ستاسو شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers34_verse_12.mp3', '', 1761754199, 1761754199),
(37516, 'Numbers 34:13', 'Numbers', 34, 13, 'نو موسی اسراییلیانو ته داسې امر وکړ: «دا هغه ځمکه ده چې تاسو به یې د پچې اچولو له مخې تر لاسه کړئ، یعنې هغه ځمکه چې څښتن د نهه نیمو قبیلو دپاره ټاکلې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers34_verse_13.mp3', '', 1761754199, 1761754199),
(37517, 'Numbers 34:14', 'Numbers', 34, 14, 'د روبین، جاد او د منسي نیمې قبیلې خپله ځمکه تر لاسه کړې ده چې د هغوی د کورنیو له مخې وېشل شوې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers34_verse_14.mp3', '', 1761754199, 1761754199),
(37518, 'Numbers 34:15', 'Numbers', 34, 15, 'دا اریحا ته مخامخ د اردن د سیند په ختیځ کې ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers34_verse_15.mp3', '', 1761754199, 1761754199),
(37519, 'Numbers 34:16', 'Numbers', 34, 16, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers34_verse_16.mp3', '', 1761754199, 1761754199),
(37520, 'Numbers 34:17', 'Numbers', 34, 17, '«العازار کاهن او د نون زوی یوشع به خلکو ته ځمکه ووېشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers34_verse_17.mp3', '', 1761754199, 1761754199),
(37521, 'Numbers 34:18', 'Numbers', 34, 18, 'د هرې قبیلې څخه یو یو مشر وټاکه چې د هغوی سره د ځمکې په وېشلو کې مرسته وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers34_verse_18.mp3', '', 1761754199, 1761754199),
(37522, 'Numbers 34:29', 'Numbers', 34, 29, 'دا هغه کسان دي چې څښتن ورباندې حکم وکړ چې د اسراییلیانو دپاره د ځمکې په وېشلو کې د العازار او یوشع سره مرسته وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers34_verse_29.mp3', '', 1761754199, 1761754199),
(37523, 'Exodus 21:1', 'Exodus', 21, 1, 'څښتن موسی ته وویل: «دا هغه قوانین دي چې ته یې باید اسراییلیانو ته ورکړې:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_1.mp3', '', 1761754199, 1761754199),
(37524, 'Exodus 21:2', 'Exodus', 21, 2, 'که چېرې تاسو یو عبرانی غلام په بیه واخلئ، هغه دې شپږ کاله ستاسو خدمت وکړي. خو په اووم کال به پرته له دې چې څه بیه ورڅخه واخیستل شي، هغه دې ازاد کړای شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_2.mp3', '', 1761754199, 1761754199),
(37525, 'Exodus 21:3', 'Exodus', 21, 3, 'که چېرې په هغه وخت کې چې هغه ستاسو غلام شوی ؤ واده یې نه ؤ کړی، نو هغه به د تګ په وخت کې خپله ښځه د ځان سره نه بیایي. خو که چېرې په هغه وخت کې چې هغه ستاسو غلام شو واده یې کړی ؤ، هغه به خپله ښځه هم د ځان سره بوځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_3.mp3', '', 1761754199, 1761754199),
(37526, 'Exodus 21:4', 'Exodus', 21, 4, 'که چېرې بادار یې ورته ښځه وکړي او هغه ښځه ورته زامن یا لورګانې وزېږوي، هغه ښځه او د هغې ماشومان د بادار کیږي او یوازې هغه سړی دې ازاد شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_4.mp3', '', 1761754199, 1761754199),
(37527, 'Exodus 21:5', 'Exodus', 21, 5, 'خو که چېرې هغه غلام داسې اعلان وکړي چې زه د خپل بادار او د خپلې ښځې او ماشومانو سره مینه لرم او نه غواړم چې ازاد شم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_5.mp3', '', 1761754199, 1761754199),
(37528, 'Exodus 21:6', 'Exodus', 21, 6, 'بیا به یې خپل بادار د عبادت ځای ته بوځي. هغه دې هلته د دروازې یا د دروازې د چوکاټ په مخکې ودروي او په ستنه باندې دې د هغه غوږ سوری کړي. بیا به دا سړی ټول عمر د هغه غلام وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_6.mp3', '', 1761754199, 1761754199),
(37529, 'Exodus 21:7', 'Exodus', 21, 7, 'که چېرې یو سړی خپله لور د یوې وینځې په توګه خرڅوي، هغه دې د نارینه غلامانو په شان ازاده نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_7.mp3', '', 1761754199, 1761754199),
(37530, 'Exodus 21:8', 'Exodus', 21, 8, 'که چېرې هغه په یو داسې کس باندې خرڅه شي چې داسې نیت ولري چې هغه خپله ښځه کړي، خو هغه یې خوښه نه شي، نو بیا دې هغه بېرته د خپل پلار له خوا په بیه واخیستل شي. د هغې بادار هغه په پردیو خلکو باندې نه شي خرڅولی، ځکه چې دا کار د هغې سره خیانت شمېرل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_8.mp3', '', 1761754199, 1761754199),
(37531, 'Exodus 21:9', 'Exodus', 21, 9, 'که چېرې یو سړی یوه وینځه واخلي چې خپل زوی ته یې وکړي، نو د هغې سره دې لکه د خپلې لور په شان چلند کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_9.mp3', '', 1761754199, 1761754199),
(37532, 'Exodus 21:10', 'Exodus', 21, 10, 'که چېرې یو سړی دوهم واده وکړي، نو باید لومړنۍ ښځه د خوړو، کالیو او د واده د حقونو څخه بې برخې نه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_10.mp3', '', 1761754199, 1761754199),
(37533, 'Exodus 21:11', 'Exodus', 21, 11, 'که چېرې هغې ته دا درې شیان نه برابروي، نو باید ازاده یې کړي او هېڅ بیه دې وانخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_11.mp3', '', 1761754199, 1761754199),
(37534, 'Exodus 21:12', 'Exodus', 21, 12, 'که چېرې څوک یو بل کس داسې ووهي چې هغه مړ شي، نو هغه کس باید ووژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_12.mp3', '', 1761754199, 1761754199),
(37535, 'Exodus 21:13', 'Exodus', 21, 13, 'خو که چېرې هغه دا کار په قصد سره نه وي کړی، خو د خدای له خوا ورته پېښه شي، نو هغه دې داسې ځای ته وتښتي چې زه یې ټاکم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_13.mp3', '', 1761754199, 1761754199),
(37536, 'Exodus 21:14', 'Exodus', 21, 14, 'خو که چېرې یو سړی دسیسه جوړه کړي او په قصدي توګه بل سړی ووژني حتی که چېرې هغه د خوندي پاتې کېدلو دپاره زما د قربانۍ ځای ته هم وتښتي، باید ووژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_14.mp3', '', 1761754199, 1761754199),
(37537, 'Exodus 21:15', 'Exodus', 21, 15, 'هرڅوک چې خپل پلار یا خپله مور ووهي، هغه باید ووژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_15.mp3', '', 1761754199, 1761754199),
(37538, 'Exodus 21:16', 'Exodus', 21, 16, 'هرڅوک چې یو بل کس وتښتوي او هغه خرڅ کړي یا تر هغه وخته پورې ورسره وي چې هغه ونیول شي، هغه باید ووژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_16.mp3', '', 1761754199, 1761754199),
(37539, 'Exodus 21:17', 'Exodus', 21, 17, 'هرڅوک چې خپل پلار یا خپلې مور ته ښکنځلې وکړي، هغه باید ووژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_17.mp3', '', 1761754199, 1761754199),
(37540, 'Exodus 21:20', 'Exodus', 21, 20, 'که چېرې یو سړی خپل غلام یا وینځه په کوتک باندې ووهي او هغه ځای په ځای مړ شي، هغه ته باید سزا ورکړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_20.mp3', '', 1761754199, 1761754199),
(37541, 'Exodus 21:21', 'Exodus', 21, 21, 'خو که چېرې دا غلام یا وینځه یوه یا دوه ورځې ژوندی پاتې شي، نو بادار ته دې سزا نه ورکول کیږي، ځکه چې دا غلام یا وینځه د هغه خپله شتمني ده او د هغه دپاره دا تاوان بس دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_21.mp3', '', 1761754199, 1761754199),
(37542, 'Exodus 21:22', 'Exodus', 21, 22, 'که چېرې څو کسان سره جګړه کوي او یوه امیدواره ښځه داسې ژوبله کړي چې خپل ماشوم له لاسه ورکړي او بل ځای یې زخمي نه شي، هر یوه چې هغه ژوبله کړې وي، نو کومه جریمه چې د هغې ښځې مېړه یې غواړي او قاضیانو ته د تایید وړ وي، هغه دې ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_22.mp3', '', 1761754199, 1761754199),
(37543, 'Exodus 21:23', 'Exodus', 21, 23, 'که چېرې په خپله دا ښځه زخمي شي، نو سزا به یې د ژوند په بدل کې ژوند وي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_23.mp3', '', 1761754199, 1761754199),
(37544, 'Exodus 21:24', 'Exodus', 21, 24, 'د سترګې په بدل کې سترګه، د غاښ په بدل کې غاښ، د لاس په بدل کې لاس، د پښې په بدل کې پښه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_24.mp3', '', 1761754199, 1761754199),
(37545, 'Exodus 21:25', 'Exodus', 21, 25, 'د سوځولو په بدل کې سوځول، د زخم په بدل کې زخم، د وهلو ټکولو په بدل کې وهل ټکول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_25.mp3', '', 1761754199, 1761754199),
(37546, 'Exodus 21:26', 'Exodus', 21, 26, 'که چېرې یو څوک خپل غلام یا وینځه په سترګه باندې ووهي او سترګه یې له منځه یوسي، هغه دې دا غلام یا وینځه د سترګې د تاوان په توګه ازاد کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_26.mp3', '', 1761754199, 1761754199),
(37547, 'Exodus 21:27', 'Exodus', 21, 27, 'که چېرې هغه د خپل غلام یا وینځې غاښ مات کړي، هغه دې د غاښ د تاوان په توګه هغه غلام یا وینځه ازاده کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_27.mp3', '', 1761754199, 1761754199),
(37548, 'Exodus 21:28', 'Exodus', 21, 28, 'که چېرې یو غویی یو څوک په ښکر ووهي چې هغه مړ شي، غویی دې سنګسار شي او د هغه غوښه دې ونه خوړل شي. خو د هغه خاوند ته به سزا نه ورکول کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_28.mp3', '', 1761754199, 1761754199),
(37549, 'Exodus 21:29', 'Exodus', 21, 29, 'خو که چېرې هغه غویي د خلکو د وهلو عادت درلود او خاوند یې ورڅخه خبر ؤ او هغه دا غویی تړلی نه وي ساتلی، نو که چېرې هغه یو سړی یا یوه ښځه داسې ووهي چې مړ شي، نو سنګسار دې شي او د هغه خاوند دې هم ووژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_29.mp3', '', 1761754199, 1761754199),
(37550, 'Exodus 21:30', 'Exodus', 21, 30, 'خو که چېرې خاوند دا اجازه ولري چې د خپل ژوند د ژغورلو دپاره تاوان ورکړي، نو هغه باید پوره بیه ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_30.mp3', '', 1761754199, 1761754199),
(37551, 'Exodus 21:31', 'Exodus', 21, 31, 'که چېرې هغه غویی د چا زوی یا لور ووهي، همدا قانون عملي کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_31.mp3', '', 1761754199, 1761754199),
(37552, 'Exodus 21:32', 'Exodus', 21, 32, 'که چېرې هغه غویی یو غلام یا وینځه ووهي، د هغه خاوند باید د سپینو زرو دېرش سکې د غلام بادار ته ورکړي او غویی باید سنګسار شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_32.mp3', '', 1761754199, 1761754199),
(37553, 'Exodus 21:33', 'Exodus', 21, 33, 'که چېرې یو سړی د یوې څاه سر لوڅ پرېږدي یا یوه کنده وکیني او هغه پټه نه کړي او یو غویی یا یو خر په کې وغورځیږي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_33.mp3', '', 1761754199, 1761754199),
(37554, 'Exodus 21:34', 'Exodus', 21, 34, 'د څاه خاوند باید د حیوان خاوند ته تاوان ورکړي او مړ حیوان به د څاه د خاوند شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_34.mp3', '', 1761754199, 1761754199),
(37555, 'Exodus 21:35', 'Exodus', 21, 35, 'که چېرې د یو سړي غویی د بل چا غویی زخمي کړي او هغه مړ شي، هغوی دې ژوندی حیوان خرڅ کړي او پیسې او مړ حیوان دواړه دې په خپل منځ کې سره مساوي ووېشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_35.mp3', '', 1761754199, 1761754199),
(37556, 'Exodus 21:36', 'Exodus', 21, 36, 'خو که چېرې دا معلومه شي چې هغه غویي د وهلو عادت درلود او بیاهم د هغه خاوند هغه تړلی نه ؤ ساتلی، هغه خاوند باید د حیوان په بدل کې حیوان ورکړي او مړ حیوان به د هغه خپل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus21_verse_36.mp3', '', 1761754199, 1761754199),
(37557, 'Psalms 28:1', 'Psalms', 28, 1, 'ای څښتنه، ای زما دفاع کوونکیه زه فریاد کومه تاته په ما دې مه کڼوه خپل غوږونه که ځواب راته رانه کړې نو زه به د هغو په شان شم چې وي روان د مرګ کندې ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms28_verse_1.mp3', '', 1761754199, 1761754199),
(37558, 'Psalms 28:2', 'Psalms', 28, 2, 'زه چې کله د کومک دپاره تاته زاري کومه ستا د ډېر سپېڅلي ځای په لور چې کړم لاسونه پورته نو قبوله مې زاري کړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms28_verse_2.mp3', '', 1761754199, 1761754199),
(37559, 'Psalms 28:3', 'Psalms', 28, 3, 'ما په هغو بدکارانو کې مه نیسه کوم چې کاندي بد کارونه هغوی تل کاندي خبرې دوستانه خو په زړونو کې یې تل وي نفرتونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms28_verse_3.mp3', '', 1761754199, 1761754199),
(37560, 'Psalms 28:4', 'Psalms', 28, 4, 'څه چې دوی کړي د هغو سزا ورکړه د هغو بدو کارونو چې دوی کړي د خپلو ټولو عملونو سزا ورکړه ته هغوی ته چې د کوم شي دوی لایق دي هغه ورکړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms28_verse_4.mp3', '', 1761754199, 1761754199),
(37561, 'Psalms 28:5', 'Psalms', 28, 5, 'هغه کارونه چې څښتن کړي دي او یا هغه څه چې جوړ کړي دي هغه هغوی یې نه ساتي پروا نو به ونړوي دوی شي راګوزار به بیا هېڅکله به هغوی نه کړي اباد', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms28_verse_5.mp3', '', 1761754199, 1761754199),
(37562, 'Psalms 28:6', 'Psalms', 28, 6, 'ثنا او صفت دې وي څښتن ته چې یې واورېدې زارۍ زما د رحم په خاطر', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms28_verse_6.mp3', '', 1761754199, 1761754199),
(37563, 'Psalms 28:7', 'Psalms', 28, 7, 'دی څښتن زما قوت او زما سپر زه د زړه نه توکل په هغه کړمه هغه کوي راسره مرسته خوشحالیږي زړګی زه یې د شکر په سندرو صفتونه کوم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms28_verse_7.mp3', '', 1761754199, 1761754199),
(37564, 'Psalms 28:8', 'Psalms', 28, 8, 'څښتن قوت ورکوي خپل ولس ته هغه کلا ده د نجات د خپل غوره پاچا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms28_verse_8.mp3', '', 1761754199, 1761754199),
(37565, 'Psalms 28:9', 'Psalms', 28, 9, 'ته خپل قوم ته نجات ورکړه ای څښتنه هغه چاته برکت ورکړه چې ستا دي ته شپونکی د هغوی اوسه همېشه ورباندې پام کړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms28_verse_9.mp3', '', 1761754199, 1761754199),
(37566, 'Exodus 16:1', 'Exodus', 16, 1, 'د اسراییلو ټول قوم د ایلیم څخه لاړ او د دوهمې میاشتې په پنځلسمه ورځ د مصر څخه د تګ نه وروسته هغوی د سین دښتې ته چې د ایلیم او سینا ترمنځ وه، راغلل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_1.mp3', '', 1761754199, 1761754199),
(37567, 'Exodus 16:2', 'Exodus', 16, 2, 'په دښته کې د اسراییلو ټول قوم موسی او هارون ته شکایت وکړ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_2.mp3', '', 1761754199, 1761754199),
(37568, 'Exodus 16:3', 'Exodus', 16, 3, 'او ورته ویې ویل: «کاشکې مونږ د څښتن په لاس په مصر کې وژل شوي وای. مونږ به هلته د غوښې د دېګونو څنګ ته کښېناستو او څومره خواړه چې مونږ غوښتل مونږ به خوړل. خو تاسو مونږ دې دښتې ته راوستلو چې ټول له لوږې ووژنئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_3.mp3', '', 1761754199, 1761754199),
(37569, 'Exodus 16:4', 'Exodus', 16, 4, 'څښتن موسی ته وویل: «اوس به زه په تاسو ټولو باندې د اسمان څخه د ډوډۍ باران ووروم. خلک دې هره ورځ ځي او د ځان دپاره دې د یوې ورځې خواړه راټولوي. په دې ډول به زه هغوی وازمایم چې زما لارښوونې ته غاړه ږدي او که نه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_4.mp3', '', 1761754199, 1761754199),
(37570, 'Exodus 16:5', 'Exodus', 16, 5, 'په شپږمه ورځ دې هغوی د دوو ورځو خواړه راوړي او ځان دپاره دې تیار کړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_5.mp3', '', 1761754199, 1761754199),
(37571, 'Exodus 16:6', 'Exodus', 16, 6, 'نو موسی او هارون ټولو اسراییلیانو ته وویل: «نن ماښام به تاسو پوه شئ چې دا څښتن ؤ چې تاسو یې د مصر څخه راوویستلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_6.mp3', '', 1761754199, 1761754199),
(37572, 'Exodus 16:7', 'Exodus', 16, 7, 'تاسو به په سهار کې د څښتن جلال ووینئ، ځکه چې هغه د خپل ځان په ضد ستاسو شکایتونه اورېدلي دي. مونږ څوک یو چې زمونږ څخه ګیله کوئ؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_7.mp3', '', 1761754199, 1761754199),
(37573, 'Exodus 16:8', 'Exodus', 16, 8, 'موسی دا هم وویل: «تاسو به پوه شئ چې دا څښتن دی چې په ماښام کې به درته غوښه او په سهار کې چې څومره ډوډۍ غواړئ درکوي، ځکه چې هغه د خپل ځان په ضد ستاسو شکایتونه اورېدلي دي. مونږ څوک یو؟ تاسو زمونږ څخه نه، بلکې له څښتن څخه شکایت کړی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_8.mp3', '', 1761754199, 1761754199),
(37574, 'Exodus 16:9', 'Exodus', 16, 9, 'موسی هارون ته وویل: «ټول قوم ته ووایه چې د څښتن په مخکې ودریږي، ځکه چې هغه د هغوی شکایتونه اورېدلي دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_9.mp3', '', 1761754199, 1761754199),
(37575, 'Exodus 16:10', 'Exodus', 16, 10, 'کله چې هارون د اسراییلو ټول قوم ته وینا کوله، هغوی د دښتې خواته وکتل او هلته د څښتن جلال په ورېځ کې ښکاره شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_10.mp3', '', 1761754199, 1761754199),
(37576, 'Exodus 16:11', 'Exodus', 16, 11, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_11.mp3', '', 1761754199, 1761754199),
(37577, 'Exodus 16:12', 'Exodus', 16, 12, '«ما د اسراییلیانو شکایتونه اورېدلي دي. هغوی ته ووایه: ماښام به تاسو غوښه وخورئ او په سهار کې به په ډوډۍ باندې ماړه شئ. بیا به تاسو پوه شئ چې زه ستاسو څښتن خدای یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_12.mp3', '', 1761754199, 1761754199),
(37578, 'Exodus 16:13', 'Exodus', 16, 13, 'ماښام د مړزانو یوه لویه ډله راغله او ټول کمپ یې ونیوه او په سهار کې د کمپ په شاوخوا کې پرخه پرته وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_13.mp3', '', 1761754199, 1761754199),
(37579, 'Exodus 16:14', 'Exodus', 16, 14, 'کله چې پرخه والوتله، په ځمکه باندې د واورې په شان واړه بڅرکي راښکاره شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_14.mp3', '', 1761754199, 1761754199),
(37580, 'Exodus 16:15', 'Exodus', 16, 15, 'کله چې اسراییلیانو هغه ولیدل، نو ویې نه پېژندل او د یو بل څخه یې پوښتنه کوله: «دا څه شی دي؟» موسی هغوی ته وویل: «دا هغه ډوډۍ ده چې څښتن تاسو ته د خوړلو دپاره درکړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_15.mp3', '', 1761754199, 1761754199),
(37581, 'Exodus 16:16', 'Exodus', 16, 16, 'څښتن حکم کړی دی چې هرڅوک دې د خپلې ورځنۍ اړتیا په اندازه هغه راټوله کړي. دوه دوه لیتره دې د خپلې کورنۍ هر یو غړي ته راټوله کړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_16.mp3', '', 1761754199, 1761754199),
(37582, 'Exodus 16:17', 'Exodus', 16, 17, 'اسراییلیانو همداسې وکړل. ځینو ډېره او ځینو لږه راټوله کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_17.mp3', '', 1761754199, 1761754199),
(37583, 'Exodus 16:18', 'Exodus', 16, 18, 'کله چې هغوی هغه اندازه کړه، چا چې ډېره راټوله کړې وه د هغه سره زیاته نه وه او چا چې لږه راټوله کړې وه د هغه سره کمه نه وه. هر یو د خپلې اړتیا په اندازه راټوله کړې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_18.mp3', '', 1761754199, 1761754199),
(37584, 'Exodus 16:19', 'Exodus', 16, 19, 'موسی هغوی ته وویل: «هېڅوک دې هغه تر سهار پورې ونه ساتي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_19.mp3', '', 1761754199, 1761754199),
(37585, 'Exodus 16:20', 'Exodus', 16, 20, 'خو د هغوی څخه ځینو موسی ته غوږ ونه نیوه او لږه یې وساتله. په راتلونکي سهار هغې چینجي وکړل او بد بوی یې کاوه، نو موسی هغوی ته په قهر شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_20.mp3', '', 1761754199, 1761754199),
(37586, 'Exodus 16:21', 'Exodus', 16, 21, 'هر سهار هرچا د خپلې اړتیا له مخې خواړه راټولول او کله به چې لمر ګرمېده، نو څه چې په ځمکه باندې پاتې کېدل هغه به ویلي کېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_21.mp3', '', 1761754199, 1761754199),
(37587, 'Exodus 16:22', 'Exodus', 16, 22, 'په شپږمه ورځ هغوی دوه چنده راټوله کړه، یعنې څلور لیتره د هر یو کس دپاره. نو د قوم ټول مشران راغلل او موسی یې خبر کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_22.mp3', '', 1761754199, 1761754199),
(37588, 'Exodus 16:23', 'Exodus', 16, 23, 'موسی هغوی ته وویل: «څښتن حکم کړی دی چې سبا د سبت یعنې د ارام کولو سپېڅلې ورځ ده چې څښتن ته وقف شوې ده. نن هرڅه چې غواړئ پاخه یې کړئ او هرڅه چې غواړئ ویې ایشوئ. هرڅه چې پاتې کیږي هغه د سهار دپاره وساتئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_23.mp3', '', 1761754199, 1761754199),
(37589, 'Exodus 16:24', 'Exodus', 16, 24, 'څنګه چې موسی امر کړی ؤ، څه چې پاتې شول هغوی تر راتلونکې ورځې پورې وساتل او هغه بوی او چینجي ونه کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_24.mp3', '', 1761754199, 1761754199),
(37590, 'Exodus 16:25', 'Exodus', 16, 25, 'موسی وویل: «دا نن وخورئ، ځکه چې نن د سبت یعنې د ارام کولو ورځ ده چې څښتن ته وقف شوې ده او تاسو به دباندې په ځمکه باندې خواړه ونه مومئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_25.mp3', '', 1761754199, 1761754199),
(37591, 'Exodus 16:26', 'Exodus', 16, 26, 'تاسو باید شپږ ورځې خواړه راټول کړئ، خو په اوومه ورځ چې د سبت ورځ ده هېڅ شی به نه وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_26.mp3', '', 1761754199, 1761754199),
(37592, 'Exodus 16:27', 'Exodus', 16, 27, 'بیاهم ځینې خلک په اوومه ورځ د خوړو د راټولولو دپاره لاړل، خو هغوی هېڅ څه ونه موندل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_27.mp3', '', 1761754199, 1761754199),
(37593, 'Exodus 16:28', 'Exodus', 16, 28, 'بیا څښتن موسی ته وویل: «تاسو به ترڅه وخته پورې زما د حکمونو او قوانینو څخه سرغړونه کوئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_28.mp3', '', 1761754199, 1761754199),
(37594, 'Exodus 16:29', 'Exodus', 16, 29, 'یاد ساتئ چې زه څښتن یم او ما تاسو ته د ارام کولو دپاره یوه ورځ درکړې ده. همدا دلیل دی چې زه به په شپږمه ورځ تل د دوه ورځو خواړه درکوم. په اوومه ورځ دې هرڅوک په خپل کور کې پاتې شي او د هغه ځای څخه دې نه راوځي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_29.mp3', '', 1761754199, 1761754199),
(37595, 'Exodus 16:30', 'Exodus', 16, 30, 'نو خلکو په اوومه ورځ ارام وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_30.mp3', '', 1761754199, 1761754199),
(37596, 'Exodus 16:31', 'Exodus', 16, 31, 'دا خواړه د اسراییلو قوم د من په نوم یادول. هغه د دڼیا د دانو په شان وو، هغه سپین وو او د شاتو په شان خوند یې درلود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_31.mp3', '', 1761754199, 1761754199),
(37597, 'Exodus 16:32', 'Exodus', 16, 32, 'موسی وویل: «څښتن حکم کړی دی چې دوه لیتره من واخلئ او د راتلونکو نسلونو دپاره یې وساتئ. نو هغوی به دا خواړه وویني چې هغه مې تاسو ته په هغه وخت کې په دښته کې درکړي وو چې کله مې د مصر څخه راوویستلئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_32.mp3', '', 1761754199, 1761754199),
(37598, 'Exodus 16:33', 'Exodus', 16, 33, 'موسی هارون ته وویل: «یو لوښی راواخله او دوه لیتره من په کې واچوه او د څښتن په حضور کې یې کېږده چې د راتلونکو نسلونو دپاره د یادګار په توګه وساتل شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_33.mp3', '', 1761754199, 1761754199),
(37599, 'Exodus 16:34', 'Exodus', 16, 34, 'څنګه چې څښتن موسی ته حکم کړی ؤ، هارون هغه د لوظ د صندوق مخې ته کېښود چې وساتل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_34.mp3', '', 1761754199, 1761754199),
(37600, 'Exodus 16:35', 'Exodus', 16, 35, 'اسراییلیانو څلوېښت کاله من وخوړ، تر هغې پورې چې هغوی د کنعان خاورې ته ورسېدل او هلته ځای په ځای شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_35.mp3', '', 1761754199, 1761754199),
(37601, 'Exodus 16:36', 'Exodus', 16, 36, '(هغه لوښی چې د من د اندازه کولو دپاره ورڅخه کار اخیستل کېده هغه د عومر په نوم یادېده او د شلو لیترو سره برابر ؤ.)', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus16_verse_36.mp3', '', 1761754199, 1761754199),
(37602, 'Psalms 135:1', 'Psalms', 135, 1, 'ثنا او صفت دې وي څښتن ته! ثنا او صفت وکړئ د هغه د نامه ای بندګانو د څښتن، د هغه ثنا او صفت وکړئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms135_verse_1.mp3', '', 1761754199, 1761754199),
(37603, 'Psalms 135:2', 'Psalms', 135, 2, 'ای هغو خلکو چې خدمت کوئ د څښتن په کور کې په حوېلۍ کې زمونږ د خدای د کور', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms135_verse_2.mp3', '', 1761754199, 1761754199),
(37604, 'Psalms 135:3', 'Psalms', 135, 3, 'د څښتن ثنا او صفت وکړئ ځکه چې نېک دی هغه ثنا او صفت یې د نامه وکړئ په سندرو سره ځکه چې خوند کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms135_verse_3.mp3', '', 1761754199, 1761754199),
(37605, 'Psalms 135:4', 'Psalms', 135, 4, 'ځکه هغه خوښ کړی دی یعقوب د خپل ځان دپاره د اسراییلو خلک چې شي د هغه خپل ملکیت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms135_verse_4.mp3', '', 1761754199, 1761754199),
(37606, 'Psalms 135:5', 'Psalms', 135, 5, 'لوی دی څښتن په دې پوهېږمه زه لوی دی څښتن زمونږه له نورو ټولو خدایانو څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms135_verse_5.mp3', '', 1761754199, 1761754199),
(37607, 'Psalms 135:6', 'Psalms', 135, 6, 'څښتن کوي هغه څه چې څه یې خوښه وي که په اسمان کې وي یا وي په ځمکه باندې که دریابونو کې وي یا یې په تل کې وي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms135_verse_6.mp3', '', 1761754199, 1761754199),
(37608, 'Psalms 135:7', 'Psalms', 135, 7, 'راولي ورېځې د دنیا له اخر سره څخه برېښنا رالېږي د بارانه سره او له خپلو ذخیرو نه رالېږي بادونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms135_verse_7.mp3', '', 1761754199, 1761754199),
(37609, 'Psalms 135:8', 'Psalms', 135, 8, 'لومړني زېږېدل شوي یې د مصریانو مړه کړل هم د انسانانو او حیواناتو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms135_verse_8.mp3', '', 1761754199, 1761754199),
(37610, 'Psalms 135:9', 'Psalms', 135, 9, 'هغه په مصر کې ښکاره کړې معجزې او ویې کړل عجیبه کارونه د فرعون او د هغه د ټولو درباریانو په ضد', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms135_verse_9.mp3', '', 1761754199, 1761754199);